// Synthetic text and service UI. No Novelpia novel content or server API is used.
export function viewerHtml() {
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>UNP Synthetic Viewer</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;color:#222}#novel_box{height:100vh;overflow-y:auto;padding:0 20px}#novel_text{max-width:900px;margin:auto}#novel_drawing_page_c{position:relative;overflow:hidden}#novel_drawing_page{column-width:880px;column-gap:20px;column-fill:auto;margin-top:10px}#header{position:fixed;top:0;left:0;right:0;z-index:100;background:white;border-bottom:1px solid #ddd;height:50px;padding:10px 8%;display:flex;justify-content:space-between}#theme_box{position:absolute;right:8%;top:48px;width:300px;display:none;background:white;color:#222;border:1px solid #ddd;z-index:110}.menu-top-setting{cursor:pointer}#navigation_group{position:absolute;bottom:70px;left:0;width:100%;padding:0 20px}#navigation_group>div{max-width:920px;margin:auto}#navigation_group table{width:100%}#page-counter-container{position:fixed;bottom:0;left:0;width:100%;height:40px;text-align:center}#footer{position:fixed;bottom:0;background:white;height:50px;left:0;right:0;z-index:90;border-top:1px solid #ddd;padding:12px;text-align:center}#novel_drawing_left,#novel_drawing_right{position:fixed;top:45%;cursor:pointer;font-size:32px;color:#7632ff;padding:12px;z-index:5}#novel_drawing_left{left:0}#novel_drawing_right{right:0}.line{font-size:18px;line-height:1.6}.line img{max-width:100%}#test-banner{position:fixed;right:2px;bottom:60px;background:#ffd56c;padding:6px;z-index:500;font-size:10px}.curation-wrapper{border:1px solid orange;padding:12px}.native-option{padding:8px}button{cursor:pointer}
</style></head><body><header id="header"><span>회귀 테스트 · 합성 본문</span><div class="menu-top-setting" onclick="btn_theme2()"><button id="btn_theme">설정</button></div><div id="theme_box"><table><tr><td id="btn_panel_1">일반설정</td><td id="btn_panel_2">고급설정</td></tr></table><div id="option_panel_1" class="native-option">기존 설정</div><div id="option_panel_2" class="native-option">기존 고급설정</div></div></header><div id="novel_box"><div id="novel_text"><div id="novel_drawing"></div><div id="novel_drawing_page_c"><div id="novel_drawing_page"></div><div id="page-counter-container"><span id="page_cnt"></span></div></div></div></div><div id="novel_drawing_left" onclick="page_back()">‹</div><div id="novel_drawing_right" onclick="page_next()">›</div><footer id="footer"><div id="navigation_group"><div><table><tbody><tr><td><button id="bookmark_div" onclick="bookmark()">북마크</button></td><td><input id="page_navigation" aria-label="기본 페이지" type="range" min="1" max="1" onchange="page_goto(Number(this.value))"></td><td><span id="this_page_view">1</span></td></tr></tbody></table></div></div><span id="recommend_tap" aria-pressed="false"><button id="menu-bottom-item" onclick="recommend()">추천</button></span><button id="native-next" onclick="document.body.dataset.episodeNext='yes'">다음화</button></footer><aside id="test-banner" data-service="ad">보존해야 하는 테스트 광고 <button onclick="this.parentNode.dataset.clicked='yes'">확인</button></aside><input id="content_no" value="1001" type="hidden"><script>
let this_page=1,max_page=1;
  if(!document.cookie.includes('NAVIGATION='))document.cookie='NAVIGATION=1; path=/';
  function bookmark(){localStorage.setItem('bookmark_1001',String(this_page));}
var option_btn_theme=0,move_key=0,redraws=0;
if(!localStorage.getItem('viewer_animation'))localStorage.setItem('viewer_animation','on');
function textLines(){let lines=[];for(let i=0;i<150;i++){let text='문단 '+i+' · 바람이 조용히 창가를 스쳤다. 서로 다른 너비와 글꼴에서도 이 문장이 순서대로 이어져야 한다. 한글과 English, 숫자 123, 이모지 🌙를 함께 읽는다. ';if(i===3)text='<b>작가가 지정한 굵은 글씨</b>와 <i>기울임</i>, <span style="font-weight:700">인라인 강조</span>를 보존한다.';if(i===8)text+='장문 '.repeat(350);if(i===20)text='<img alt="테스트 삽화" width="500" height="250" src="data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%27500%27 height=%27250%27%3E%3Crect width=%27500%27 height=%27250%27 fill=%27%23dac7ff%27/%3E%3C/svg%3E">';if(i%11===0)text='&nbsp;';lines.push(text);}return lines;}
function viewer_display(){redraws++;document.body.dataset.redraws=String(redraws);const page=localStorage.getItem('viewer_paging')==='1';const scroll=document.getElementById('novel_drawing');const root=document.getElementById('novel_drawing_page');const c=document.getElementById('novel_drawing_page_c');scroll.innerHTML='';root.innerHTML='';scroll.style.display=page?'none':'block';c.style.display=page?'block':'none';root.style.height=(innerHeight-60)+'px';const tag=page?'span':'font';(page?root:scroll).innerHTML=textLines().map((text,i)=>'<'+tag+' class="line" data-line="'+i+'">'+text+'</'+tag+'><br>').join('')+'<div class="curation-wrapper" data-service="curation">사이트 후기/추천 영역</div>';
document.getElementById('writer_comments_box')?.remove();const note=document.createElement('div');note.id='writer_comments_box';note.style.cssText='color:#222222;background-color:rgba(155,155,155,.1);border:1px solid #ddd;padding:10px 20px';note.innerHTML='<i class="icon"></i>합성 작가의 한마디<br>줄바꿈과 <b>강조</b>를 보존한다.';document.getElementById('novel_text').append(note);
document.getElementById('navigation_group').style.display=document.cookie.includes('NAVIGATION=0')?'none':'block';document.getElementById('novel_drawing_left').style.display=page?'block':'none';document.getElementById('novel_drawing_right').style.display=page?'block':'none';setTimeout(page_cal,500);}
function page_width(){return document.getElementById('novel_drawing_page_c').clientWidth+20;}
function page_cal(){const c=document.getElementById('novel_drawing_page_c');const root=document.getElementById('novel_drawing_page');if(!root.children.length)return;const last=[...root.querySelectorAll('*')].at(-1);const left=last.getBoundingClientRect().left-c.getBoundingClientRect().left+c.scrollLeft;max_page=Math.max(1,Math.ceil(left/(c.clientWidth+20)));document.getElementById('page_cnt').textContent=this_page+'/'+max_page;document.getElementById('this_page_view').textContent=String(this_page);document.getElementById('page_navigation').max=String(max_page);document.querySelector('.curation-wrapper').style.display=this_page===max_page?'block':'none';document.body.dataset.nativeTotal=String(max_page);}
function page_goto(n){this_page=Math.max(1,Math.min(n,max_page));document.getElementById('novel_drawing_page_c').scrollLeft=page_width()*(this_page-1);page_cal();}
function page_next(){if(this_page===max_page&&localStorage.getItem('viewer_nextepi')==='on'){document.body.dataset.episodeNext='yes';return;}page_goto(this_page+1);}
function page_back(){page_goto(this_page-1);}
function btn_theme2(){option_btn_theme=option_btn_theme?0:1;document.getElementById('theme_box').style.display=option_btn_theme?'block':'none';}
function viewer_1_btn(){localStorage.setItem('viewer_paging','0');location.reload();}function viewer_2_btn(){localStorage.setItem('viewer_paging','1');location.reload();}
function dark_on_btn(){document.cookie='DARKMODE=1; path=/';viewer_display();}function dark_off_btn(){document.cookie='DARKMODE=0; path=/';viewer_display();}
function img_on_btn(){document.cookie='BLOCK_ILLUSTRATION=OFF; path=/';document.querySelectorAll('.line img').forEach(e=>e.style.display='');}function img_off_btn(){document.cookie='BLOCK_ILLUSTRATION=ON; path=/';document.querySelectorAll('.line img').forEach(e=>e.style.display='none');}
function animation_on_btn(){localStorage.setItem('viewer_animation','on');}function animation_off_btn(){localStorage.setItem('viewer_animation','off');}
function auto_nextepi_on_btn(){localStorage.setItem('viewer_nextepi','on');}function auto_nextepi_off_btn(){localStorage.setItem('viewer_nextepi','');}
function navigation_on_btn(){document.cookie='NAVIGATION=1; path=/';document.getElementById('navigation_group').style.display='block';}function navigation_off_btn(){document.cookie='NAVIGATION=0; path=/';document.getElementById('navigation_group').style.display='none';}
function recommend(){let el=document.getElementById('recommend_tap');el.setAttribute('aria-pressed',el.getAttribute('aria-pressed')==='true'?'false':'true');document.body.dataset.recommendClicks=String(Number(document.body.dataset.recommendClicks||0)+1);}
if(location.search.includes('controls')){
 const render=viewer_display;viewer_display=function(){render();const next=document.createElement('div');next.id='next_epi_btn_bottom';next.style.cssText='color:#d7c400;background:rgba(155,155,155,.1);padding:10px 20px;margin:30px 0 100px';next.textContent='다음화 보기';next.onclick=()=>{document.body.dataset.episodeNext='yes'};document.getElementById(localStorage.getItem('viewer_paging')==='1'?'novel_drawing_page':'novel_drawing').append(next);};
}
if(location.search.includes('terminal')){
 const render=viewer_display;viewer_display=function(){render();const page=localStorage.getItem('viewer_paging')==='1',body=document.getElementById(page?'novel_drawing_page':'novel_drawing');body.querySelector('.curation-wrapper')?.remove();body.append(document.getElementById('writer_comments_box'));const end=document.createElement('div');end.id='episode-end';end.textContent='등록된 마지막 회차입니다';end.style.cssText='padding:24px;border:1px solid #ddd';body.append(end);if(!document.getElementById('fixed-curation')){const service=document.createElement('aside');service.id='fixed-curation';service.className='curation-wrapper';service.dataset.service='curation';service.style.cssText='position:fixed;bottom:60px;left:0;width:100%;height:250px;display:none;background:#eee;z-index:80';service.innerHTML='<h3>공모전 다른 작품</h3><button onclick="document.body.dataset.curationClicked=1">합성 추천 작품</button>';document.body.append(service);}};
 document.getElementById('novel_box').addEventListener('scroll',function(){if(localStorage.getItem('viewer_paging')!=='1'){const c=document.getElementById('fixed-curation');if(c)c.style.display=this.scrollTop+this.clientHeight>=this.scrollHeight-100?'block':'none';}});
}
document.onkeydown=e=>{if(option_btn_theme)return;if(e.key==='ArrowRight')page_next();if(e.key==='ArrowLeft')page_back();};
setTimeout(viewer_display,120);
</script></body></html>`;
}
